core_reasoning_2:
\subsection*{Claim}
For the coherent state
\[
|\alpha\rangle=e^{-|\alpha|^2/2}\sum_{n=0}^{\infty}\frac{\alpha^n}{\sqrt{n!}}|n\rangle,
\]
the number-basis measurement probability is the Poisson law
\[
P_n=|\langle n|\alpha\rangle|^2=e^{-\lambda}\frac{\lambda^n}{n!},
\qquad \lambda:=|\alpha|^2.
\]

\subsection*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \langle n|m\rangle=\delta_{nm}\quad\text{for all }n,m\in\mathbb{N}_0.\\
\text{(P2)} & |\alpha\rangle:=e^{-|\alpha|^2/2}\sum_{m=0}^{\infty}\dfrac{\alpha^m}{\sqrt{m!}}|m\rangle.\\
\text{(P3)} & P_n:=|\langle n|\alpha\rangle|^2.\\
\text{(P4)} & \lambda:=|\alpha|^2.\\
\text{(P5)} & |zw|^2=|z|^2|w|^2\quad\text{for complex }z,w.\\
\text{(P6)} & |e^{-x/2}|^2=e^{-x}\quad\text{for real }x.\\
\text{(P7)} & |\alpha^n|^2=|\alpha|^{2n}\quad\text{for }n\in\mathbb{N}_0.
\end{array}
\]

\subsection*{Derivation}
\begin{align}
\langle n|\alpha\rangle
&=\left\langle n\middle|e^{-|\alpha|^2/2}\sum_{m=0}^{\infty}\frac{\alpha^m}{\sqrt{m!}}\middle|m\right\rangle
  &&\text{by (P2)}\\
&=e^{-|\alpha|^2/2}\sum_{m=0}^{\infty}\frac{\alpha^m}{\sqrt{m!}}\langle n|m\rangle
  &&\text{linearity}\\
&=e^{-|\alpha|^2/2}\sum_{m=0}^{\infty}\frac{\alpha^m}{\sqrt{m!}}\delta_{nm}
  &&\text{by (P1)}\\
&=e^{-|\alpha|^2/2}\frac{\alpha^n}{\sqrt{n!}}
  &&\text{Kronecker-delta reduction}.
\end{align}
Therefore,
\begin{align}
P_n
&=|\langle n|\alpha\rangle|^2
  &&\text{by (P3)}\\
&=\left|e^{-|\alpha|^2/2}\frac{\alpha^n}{\sqrt{n!}}\right|^2
  &&\text{substitution from above}\\
&=|e^{-|\alpha|^2/2}|^2\frac{|\alpha^n|^2}{n!}
  &&\text{by (P5)}\\
&=e^{-|\alpha|^2}\frac{|\alpha|^{2n}}{n!}
  &&\text{by (P6) and (P7)}\\
&=e^{-\lambda}\frac{\lambda^n}{n!}
  &&\text{by (P4)}.
\end{align}

\subsection*{Final Result}
\[
\boxed{P_n=|\langle n|\alpha\rangle|^2=e^{-\lambda}\frac{\lambda^n}{n!},\qquad \lambda=|\alpha|^2}
\]
\hfill$\blacksquare$

core_reasoning_4:
\subsection*{Claim}
For \(N\in\mathbb{N}\) and \(0\leq p\leq 1\), the finite stochastic state
\[
|\psi_B\rangle=\sum_{n=0}^{N}\sqrt{\binom{N}{n}}\,p^{n/2}(1-p)^{(N-n)/2}|n\rangle
\]
is normalized, and the number-basis probability is the Binomial law
\[
P_B(n,p)=\binom{N}{n}p^n(1-p)^{N-n},\qquad n=0,\ldots,N.
\]

\subsection*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & \langle n|m\rangle=\delta_{nm}\quad\text{for }0\leq n,m\leq N.\\
\text{(P2)} & |\psi_B\rangle:=\sum_{n=0}^{N}\sqrt{\binom{N}{n}}\,p^{n/2}(1-p)^{(N-n)/2}|n\rangle.\\
\text{(P3)} & P_B(n,p):=|\langle n|\psi_B\rangle|^2.\\
\text{(P4)} & \sum_{n=0}^{N}\binom{N}{n}x^ny^{N-n}=(x+y)^N.\\
\text{(P5)} & x:=p,\quad y:=1-p,\quad 0\leq p\leq 1.
\end{array}
\]

\subsection*{Derivation}
\begin{align}
\langle n|\psi_B\rangle
&=\sum_{m=0}^{N}\sqrt{\binom{N}{m}}\,p^{m/2}(1-p)^{(N-m)/2}\langle n|m\rangle
  &&\text{by (P2)}\\
&=\sum_{m=0}^{N}\sqrt{\binom{N}{m}}\,p^{m/2}(1-p)^{(N-m)/2}\delta_{nm}
  &&\text{by (P1)}\\
&=\sqrt{\binom{N}{n}}\,p^{n/2}(1-p)^{(N-n)/2}
  &&\text{Kronecker-delta reduction}.
\end{align}
Thus,
\begin{align}
P_B(n,p)
&=|\langle n|\psi_B\rangle|^2
  &&\text{by (P3)}\\
&=\binom{N}{n}p^n(1-p)^{N-n}
  &&\text{squaring the nonnegative amplitude}.
\end{align}
The normalization is
\begin{align}
\langle \psi_B|\psi_B\rangle
&=\sum_{n=0}^{N}|\langle n|\psi_B\rangle|^2
  &&\text{by (P1)}\\
&=\sum_{n=0}^{N}\binom{N}{n}p^n(1-p)^{N-n}
  &&\text{from the probability computation}\\
&=\sum_{n=0}^{N}\binom{N}{n}x^ny^{N-n}
  &&\text{by (P5)}\\
&=(x+y)^N
  &&\text{by (P4)}\\
&=(p+1-p)^N
  &&\text{by (P5)}\\
&=1.
\end{align}

\subsection*{Final Result}
\[
\boxed{\langle \psi_B|\psi_B\rangle=1\quad\text{and}\quad P_B(n,p)=\binom{N}{n}p^n(1-p)^{N-n}}
\]
\hfill$\blacksquare$

core_reasoning_7:
\subsection*{Claim}
For a stochastic state \(|\psi\rangle=\sum_{k}\alpha_k|k\rangle\) with \(P(k):=|\alpha_k|^2\), the quantum Shannon entropy defined by
\[
S(\psi):=-\sum_k |\alpha_k|^2\log |\alpha_k|^2
\]
is exactly the classical Shannon entropy of the associated probability law:
\[
S(\psi)=-\sum_k P(k)\log P(k).
\]

\subsection*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & |\psi\rangle:=\sum_k\alpha_k|k\rangle.\\
\text{(P2)} & P(k):=|\alpha_k|^2.\\
\text{(P3)} & S(\psi):=-\sum_k |\alpha_k|^2\log |\alpha_k|^2.\\
\text{(P4)} & \sum_k P(k)=1\text{ and every term with }P(k)=0\text{ is interpreted by }0\log 0:=0.\\
\text{(P5)} & \sum_k |P(k)\log P(k)|<\infty\text{ whenever the entropy is finite.}
\end{array}
\]

\subsection*{Derivation}
\begin{align}
S(\psi)
&=-\sum_k |\alpha_k|^2\log |\alpha_k|^2
  &&\text{by (P3)}\\
&=-\sum_k P(k)\log P(k)
  &&\text{by substituting (P2)}.
\end{align}
The normalization condition ensures that \(P(k)\) is a probability mass function:
\begin{align}
\sum_k P(k)&=1
  &&\text{by (P4)}.
\end{align}
Thus the entropy computed from squared amplitudes is the entropy computed from the corresponding classical probabilities.

\subsection*{Final Result}
\[
\boxed{S(\psi)=-\sum_k |\alpha_k|^2\log |\alpha_k|^2=-\sum_k P(k)\log P(k)}
\]
\hfill$\blacksquare$

core_reasoning_9:
\subsection*{Claim}
For the Poisson stochastic amplitude
\[
\alpha^{(P)}_k(\lambda)=\sqrt{e^{-\lambda}\frac{\lambda^k}{k!}},
\qquad \lambda>0,
\]
the quantum Fisher information defined by
\[
F(\psi_P):=4\sum_{k=0}^{\infty}\left|\frac{d\alpha^{(P)}_k}{d\lambda}\right|^2
\]
equals the classical Poisson Fisher information \(1/\lambda\).

\subsection*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & P_\lambda(k):=e^{-\lambda}\dfrac{\lambda^k}{k!},\quad k\in\mathbb{N}_0,
\quad \lambda>0.\\
\text{(P2)} & \alpha^{(P)}_k(\lambda):=\sqrt{P_\lambda(k)}.\\
\text{(P3)} & F(\psi_P):=4\sum_{k=0}^{\infty}\left|d\alpha^{(P)}_k/d\lambda\right|^2.\\
\text{(P4)} & \dfrac{d}{d\lambda}\log P_\lambda(k)=-1+\dfrac{k}{\lambda}=\dfrac{k-\lambda}{\lambda}.\\
\text{(P5)} & \sum_{k=0}^{\infty}P_\lambda(k)(k-\lambda)^2=\lambda.
\end{array}
\]

\subsection*{Derivation}
\begin{align}
\frac{d\alpha^{(P)}_k}{d\lambda}
&=\frac{d}{d\lambda}\sqrt{P_\lambda(k)}
  &&\text{by (P2)}\\
&=\frac{1}{2}\sqrt{P_\lambda(k)}\frac{d}{d\lambda}\log P_\lambda(k)
  &&\text{logarithmic derivative}\\
&=\frac{1}{2}\alpha^{(P)}_k(\lambda)\frac{k-\lambda}{\lambda}
  &&\text{by (P2) and (P4)}.
\end{align}
Therefore,
\begin{align}
F(\psi_P)
&=4\sum_{k=0}^{\infty}\left|\frac{d\alpha^{(P)}_k}{d\lambda}\right|^2
  &&\text{by (P3)}\\
&=4\sum_{k=0}^{\infty}\left|\frac{1}{2}\alpha^{(P)}_k(\lambda)\frac{k-\lambda}{\lambda}\right|^2
  &&\text{substitution from above}\\
&=\sum_{k=0}^{\infty}|\alpha^{(P)}_k(\lambda)|^2\frac{(k-\lambda)^2}{\lambda^2}
  &&\text{simplifying }4\cdot(1/2)^2\\
&=\frac{1}{\lambda^2}\sum_{k=0}^{\infty}P_\lambda(k)(k-\lambda)^2
  &&\text{by (P2)}\\
&=\frac{\lambda}{\lambda^2}
  &&\text{by (P5)}\\
&=\frac{1}{\lambda}.
\end{align}

\subsection*{Final Result}
\[
\boxed{F(\psi_P)=\frac{1}{\lambda}}
\]
\hfill$\blacksquare$

core_reasoning_11:
\subsection*{Claim}
For \(M\geq 2\), modular projection of Negative Binomial, Binomial, and Poisson count laws converges exponentially to the uniform distribution on \(\{0,\ldots,M-1\}\). More precisely, for every residue \(r\),
\[
\Pr[N\bmod M=r]=\frac{1}{M}+O(\rho^m),
\]
where \(m=r_0\) for \(N\sim NB(r_0,q)\), \(m=n\) for \(N\sim Bin(n,p)\), and \(m=\lambda\) for \(N\sim Pois(\lambda)\), with a corresponding constant \(0<\rho<1\). The Negative Binomial success parameter \(q\) may be set to \(q=1-p\) to match the zero-based amplitude convention \(\binom{k+r_0-1}{k}(1-p)^{r_0}p^k\).

\subsection*{Premises}
\[
\begin{array}{ll}
\text{(P1)} & M\in\mathbb{N},\ M\geq 2,\quad \theta_\ell:=2\pi\ell/M,
\quad \ell=0,\ldots,M-1.\\
\text{(P2)} & \Pr[N\bmod M=r]=\dfrac{1}{M}\sum_{\ell=0}^{M-1}\phi(\theta_\ell)e^{-i\ell\theta_1 r},\quad \phi(0)=1.\\
\text{(P3)} & \left|\Pr[N\bmod M=r]-\dfrac{1}{M}\right|\leq \dfrac{1}{M}\sum_{\ell=1}^{M-1}|\phi(\theta_\ell)|.\\
\text{(P4)} & \phi_{NB}(\theta)=\left(\dfrac{q}{1-(1-q)e^{i\theta}}\right)^{r_0},\quad 0<q<1,
\quad r_0\in\mathbb{N}.\\
\text{(P5)} & \phi_B(\theta)=(1-p+pe^{i\theta})^n,
\quad 0<p<1,
\quad n\in\mathbb{N}.\\
\text{(P6)} & \phi_P(\theta)=\exp\{\lambda(e^{i\theta}-1)\},
\quad \lambda>0.\\
\text{(P7)} & |1-(1-q)e^{i\theta}|^2=q^2+2(1-q)(1-\cos\theta).\\
\text{(P8)} & |1-p+pe^{i\theta}|^2=1-2p(1-p)(1-\cos\theta).\\
\text{(P9)} & |\exp\{\lambda(e^{i\theta}-1)\}|=\exp\{\lambda(\cos\theta-1)\}.\\
\text{(P10)} & \ell\in\{1,\ldots,M-1\}\Rightarrow \cos\theta_\ell<1.
\end{array}
\]

\subsection*{Derivation}
Separate the zero-frequency term in the modular Fourier formula:
\begin{align}
\Pr[N\bmod M=r]-\frac{1}{M}
&=\frac{1}{M}\sum_{\ell=1}^{M-1}\phi(\theta_\ell)e^{-i\ell\theta_1 r}
  &&\text{by (P2) and }\phi(0)=1.
\end{align}
Taking absolute values gives (P3). For the Negative Binomial law,
\begin{align}
\left|\frac{q}{1-(1-q)e^{i\theta_\ell}}\right|^2
&=\frac{q^2}{|1-(1-q)e^{i\theta_\ell}|^2}
  &&\text{modulus quotient}\\
&=\frac{q^2}{q^2+2(1-q)(1-\cos\theta_\ell)}
  &&\text{by (P7)}\\
&<1
  &&\text{by (P10) and }0<q<1.
\end{align}
Define
\begin{align}
\rho_{NB}&:=\max_{1\leq\ell\leq M-1}\left|\frac{q}{1-(1-q)e^{i\theta_\ell}}\right|.
\end{align}
The maximum is over finitely many positive numbers strictly less than \(1\), so \(0<\rho_{NB}<1\). Therefore,
\begin{align}
|\phi_{NB}(\theta_\ell)|
&\leq \rho_{NB}^{r_0}
  &&\text{by (P4)},\\
\left|\Pr[N_{NB}\bmod M=r]-\frac{1}{M}\right|
&\leq\frac{M-1}{M}\rho_{NB}^{r_0}
  &&\text{by (P3)}.
\end{align}
For the Binomial law,
\begin{align}
|1-p+pe^{i\theta_\ell}|^2
&=1-2p(1-p)(1-\cos\theta_\ell)
  &&\text{by (P8)}\\
&<1
  &&\text{by (P10) and }0<p<1.
\end{align}
Define
\begin{align}
\rho_B&:=\max_{1\leq\ell\leq M-1}|1-p+pe^{i\theta_\ell}|.
\end{align}
Then \(0<\rho_B<1\), and
\begin{align}
|\phi_B(\theta_\ell)|
&\leq\rho_B^n
  &&\text{by (P5)},\\
\left|\Pr[N_B\bmod M=r]-\frac{1}{M}\right|
&\leq\frac{M-1}{M}\rho_B^n
  &&\text{by (P3)}.
\end{align}
For the Poisson law,
\begin{align}
|\phi_P(\theta_\ell)|
&=\exp\{\lambda(\cos\theta_\ell-1)\}
  &&\text{by (P9)}.
\end{align}
Define
\begin{align}
\rho_P&:=\max_{1\leq\ell\leq M-1}\exp\{\cos\theta_\ell-1\}.
\end{align}
Since \(\cos\theta_\ell<1\), \(0<\rho_P<1\), and
\begin{align}
|\phi_P(\theta_\ell)|
&\leq\rho_P^\lambda,\\
\left|\Pr[N_P\bmod M=r]-\frac{1}{M}\right|
&\leq\frac{M-1}{M}\rho_P^\lambda
  &&\text{by (P3)}.
\end{align}
Each case has the form \(C\rho^m\) with \(C=(M-1)/M\) and \(0<\rho<1\).

\subsection*{Final Result}
\[
\boxed{\Pr[N\bmod M=r]=\frac{1}{M}+O(\rho^m),\quad 0<\rho<1,
\quad m=r_0\text{ for }NB,\ m=n\text{ for }Bin,\ m=\lambda\text{ for }Pois}
\]
\hfill$\blacksquare$
